/**
 * The built-in catalog.
 *
 * `data/seed-catalog.json` is generated by `scripts/build-seed-catalog.mjs` from
 * public Internet Archive queries (public-domain 78rpm sides, Musopen classical
 * recordings, Creative Commons netlabel releases). It gives a fresh install
 * something to browse instantly and works as a fallback when a live search
 * fails. Live searches are always preferred when the network is available.
 */

import { promises as fs } from 'node:fs'
import path from 'node:path'
import { app } from 'electron'
import type { Track } from '@shared/types'

export { deriveGenres } from '@shared/genres'

interface SeedFile {
  generatedAt?: string
  trackCount?: number
  shelves?: { id: string; title: string }[]
  tracks: Track[]
}

let seedCache: Track[] | null = null

function candidatePaths(): string[] {
  const candidates: string[] = []
  const override = process.env.KOLAARS_SEED_CATALOG
  if (override) candidates.push(override)

  // Production: extraResource / resources/app/data
  candidates.push(path.join(process.resourcesPath ?? '', 'data', 'seed-catalog.json'))
  // Packaged asar: unpacked resources
  candidates.push(path.join(process.resourcesPath ?? '', 'app.asar.unpacked', 'data', 'seed-catalog.json'))
  // Development: repo root relative to out/main
  candidates.push(path.resolve(app.getAppPath(), 'data', 'seed-catalog.json'))
  candidates.push(path.resolve(__dirname, '../../data/seed-catalog.json'))
  candidates.push(path.resolve(process.cwd(), 'data', 'seed-catalog.json'))
  return candidates
}

export async function loadSeedCatalog(): Promise<Track[]> {
  if (seedCache) return seedCache
  for (const candidate of candidatePaths()) {
    if (!candidate) continue
    try {
      const text = await fs.readFile(candidate, 'utf8')
      const parsed = JSON.parse(text) as SeedFile
      const tracks = Array.isArray(parsed.tracks) ? parsed.tracks : []
      if (tracks.length > 0) {
        seedCache = tracks.map((track) => ({ ...track, source: 'seed' as const }))
        return seedCache
      }
    } catch {
      /* try the next location */
    }
  }
  seedCache = []
  return seedCache
}
